from .core import *

def make(family,v,n):
    total=24+12*v;part=F(2,3);amount=total*part
    if family in ['fraction_part','compose_fraction']:
        tasks=[number(f'В наборе {total} деталей. Сколько составляет половина?',total//2,'Целое раздели на 2.'),number(f'Найди 1/3 от {total}.',total//3,'Раздели число на знаменатель.'),number(f'Найди 2/3 от {total}.',amount,'Найди одну треть, затем возьми две.'),number(f'2/3 всех книг — это {f(amount)} книг. Сколько книг всего?',total,'Раздели известную часть на дробь.'),choice(f'Для задачи «2/3 от {total}» подходит вопрос…','Сколько книг составляет две трети фонда?',['Сколько книг составляет две трети фонда?','Чему равна разность 2 и 3?','Сколько раз 2 больше 3?'],'Слова «доля от числа» связывают часть и целое.'),number(f'Для кружка купили {total} листов. 3/4 использовали. Сколько осталось?',total//4,'Можно найти оставшуюся долю: 1 − 3/4 = 1/4.')]
        return package('Найди часть и восстанови целое',['Чтобы найти дробь от числа, умножь число на дробь.','Чтобы найти число по известной дроби, раздели часть на эту дробь.','Для своей задачи укажи целое, долю и вопрос; единицы должны совпадать.'],['2/3 от 18 — это 12','18 ÷ 3 × 2 = 12. Обратно: 12 ÷ 2 × 3 = 18.'],'Составь две связанные задачи о книгах школьной библиотеки: на часть числа и на восстановление целого. Запиши решения и ответы.',tasks)
    if family=='joint_work':
        a=4+2*v;b=2+v;rate=F(1,a)+F(1,b);time=1/rate
        tasks=[number(f'Первый насос заполняет бак за {a} ч. Какую часть бака за 1 ч?',F(1,a),'Весь бак — единица. Работа идёт с постоянной скоростью.'),number(f'Второй насос заполняет такой же бак за {b} ч. Какая часть за 1 ч?',F(1,b),'Раздели единицу на время.'),expr('Какую часть бака заполнят оба насоса за час?',F(1,a),F(1,b),'+','Насосы работают одновременно, без потерь и помех. Складывай производительности.'),choice('Для времени совместной работы нужно…','1 разделить на общую производительность',['Сложить отдельные времена','1 разделить на общую производительность','Вычесть времена'],'Весь объём равен 1.'),number(f'Насосы заполняют по 1/{a} и 1/{b} бака в час. За сколько часов вместе заполнят бак?',time,'Раздели 1 на сумму долей за час.'),choice(f'Совместное время меньше {b} ч?','Да',['Да','Нет'],'При совместной работе и отсутствии помех работают быстрее каждого отдельно.')]
        return package('Команда наполняет бак',['За единицу принимают всю работу. За час выполняют долю 1/t, где t — время всей работы.','При совместной работе складывают доли за час, затем делят всю работу на общую производительность.'],['Один насос: 6 ч, другой: 3 ч','За час: 1/6 + 1/3 = 1/2 бака. Вместе: 1 ÷ 1/2 = 2 ч. Модель предполагает постоянную подачу воды.'],'Нарисуй бак и подпиши доли работы двух насосов за час. Объясни, почему нельзя просто сложить времена.',tasks)
    raise ValueError(family)
